mapper.update:
UPDATE conversation_member
SET unread_count = unread_count + 1
WHERE conversation_id = #{conversationId}
  AND user_id != #{excludeUserId}

UPDATE conversation_member
SET unread_count = 0
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}

UPDATE conversation_member
SET is_deleted = 1
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}

mapper.select:
SELECT COUNT(1) > 0
FROM conversation_member
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND is_deleted = 0
